#!/usr/bin/env python3
"""Audit publication filtering against saved inventory without a database connection."""
import argparse
import hashlib
import json
from pathlib import Path
import sys
from urllib.parse import unquote, urlsplit

REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO))
from scripts.generator_publish import ImageLibrary, enum, localize_record, prepare_records


class AuditImages(ImageLibrary):
    """Read canonical images in place; store all localized bytes under evidence."""
    def __init__(self, output_root, asset_root, canonical_root):
        super().__init__(output_root, asset_root)
        self.canonical_root = Path(canonical_root).resolve()

    def resolve(self, source):
        reference = source.strip().strip('<>')
        mapped = self.mapping.get(reference, reference)
        parsed = urlsplit(mapped)
        relative = Path(unquote(parsed.path))
        if not parsed.scheme and relative.parts[:1] == ('images',):
            candidate = (self.canonical_root / relative).resolve()
            if candidate.is_relative_to(self.canonical_root) and candidate.is_file():
                data = candidate.read_bytes()
                expected = self.expected_hashes.get(mapped)
                if expected and hashlib.sha256(data).hexdigest() != expected:
                    raise ValueError('Captured image differs from its source manifest: ' + source)
                return self.store(data, source)
        return super().resolve(source)


def audit(records, inventory, source, difficulty, output, asset_root, math_root):
    output, math_root = Path(output).resolve(), Path(math_root).resolve()
    if output.is_relative_to(math_root):
        raise ValueError('Audit output must be outside the published math root')
    if not isinstance(records, list):
        raise ValueError('Input must be a JSON array of generated records')
    for key in ('database', 'lineage', 'kp_id'):
        if inventory.get(key) != source[key]:
            raise ValueError('Inventory/source mismatch: ' + key)
    if any(enum(r['question'].get(':question/difficulty')) != ':question.difficulty/' + difficulty for r in records):
        raise ValueError('Input contains a record outside the requested difficulty; the runner rejects this batch')
    kp_uuid = source['material']['kp'][':knowledge-point/id']
    staged = output / 'assets'

    def localize(record, _math_root, _asset_root):
        return localize_record(record, staged, asset_root,
                               library=AuditImages(staged, asset_root, math_root))

    accepted, duplicates = prepare_records(records, source['kp_id'], kp_uuid,
        inventory['fingerprints'], staged, asset_root, localizer=localize)
    output.mkdir(parents=True, exist_ok=True)
    (output / 'accepted.json').write_text(json.dumps(accepted, indent=2, ensure_ascii=False) + '\n')
    report = {
        'database_writes': 0, 'inventory_basis': inventory['basis'],
        'kp_id': source['kp_id'], 'difficulty': difficulty,
        'input_count': len(records), 'duplicate_count': duplicates, 'accepted_count': len(accepted),
        'accepted_file': 'accepted.json', 'asset_root': 'assets',
        'stages_examined': ['requested difficulty', 'knowledge-point identity', 'image localization',
                            'question validation', 'stable identities', 'inventory and batch deduplication'],
        'limits': ['Uses captured inventory; concurrent publication may change duplicates.',
                   'Does not examine generator rejection/resampling or certify mathematical or pedagogical correctness.',
                   'Does not simulate learner history, weighted selection, database identity collisions, or publication.'],
    }
    (output / 'delivery.json').write_text(json.dumps(report, indent=2) + '\n')
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ('input', 'inventory', 'source', 'output'):
        parser.add_argument('--' + name, type=Path, required=True)
    parser.add_argument('--difficulty', choices=('easy', 'moderate', 'hard'), required=True)
    parser.add_argument('--asset-root', type=Path, help='Generated asset directory; defaults to input parent')
    parser.add_argument('--math-root', type=Path, default=Path('/media/jake/SSD/EDB/math'))
    args = parser.parse_args()
    paths = {'input': args.input, 'inventory': args.inventory, 'source': args.source}
    data = {name: json.loads(path.read_text()) for name, path in paths.items()}
    report = audit(data['input'], data['inventory'], data['source'], args.difficulty,
                   args.output, args.asset_root or args.input.resolve().parent, args.math_root)
    report['input_sha256'] = {name: hashlib.sha256(path.read_bytes()).hexdigest() for name, path in paths.items()}
    report['implementation_sha256'] = {str(path.relative_to(REPO)): hashlib.sha256(path.read_bytes()).hexdigest()
        for path in (Path(__file__), REPO / 'scripts/generator_publish.py', REPO / 'capture/scripts/database/images.py')}
    (args.output / 'delivery.json').write_text(json.dumps(report, indent=2) + '\n')
    print(json.dumps({key: report[key] for key in ('input_count', 'duplicate_count', 'accepted_count', 'inventory_basis')}
                     | {'report': str(args.output / 'delivery.json')}))


if __name__ == '__main__':
    main()
//! Generic in-memory grading checks through the real application; never accesses EDB.
use course_academy_engine::{learning, schema::{EntitySnapshot, Record}};
use serde_json::{Value, json};
use std::{collections::BTreeMap, error::Error, fs};
fn record(v: Value)->Record {v.as_object().unwrap().clone()}
fn main()->Result<(),Box<dyn Error>> {
 let args:Vec<_>=std::env::args().skip(1).collect();
 if args.len()!=2{return Err("check-engine INPUT.json REPORT.json".into())}
 let input:Value=serde_json::from_str(&fs::read_to_string(&args[0])?)?;
 let(mut accepted,mut rejected,mut unresolved)=(0,0,0);let mut reports=vec![];
 for item in input.as_array().ok_or("records array required")? {
  let q=&item["record"]["question"];let fields=q[":question/answer-fields"].as_array().ok_or("fields required")?;
  let mut entities=BTreeMap::new();let mut maps=vec![];let mut field_ids=vec![];let mut next_answer=100u64;
  let mut enum_names=std::collections::BTreeSet::new();
  for f in fields {enum_names.insert(f[":answer-field/type"].as_str().ok_or("field enum")?.trim_start_matches(':').to_owned());
   for a in f[":answer-field/choices"].as_array().ok_or("choices")?{enum_names.insert(a[":answer/type"].as_str().ok_or("answer enum")?.trim_start_matches(':').to_owned());}}
  for(i,name)in enum_names.into_iter().enumerate(){if i>=19{return Err("too many fixture enums".into())}entities.insert(i as u64+1,record(json!({"db/ident":name})));}

  for(i,f)in fields.iter().enumerate(){
   let field_id=20+i as u64;field_ids.push(field_id);let mut ids=vec![];let mut by_uuid=BTreeMap::new();let mut correct=None;
   let correct_uuid=f[":answer-field/correct"].get(1).and_then(Value::as_str).ok_or("correct lookup ref required")?;
   for a in f[":answer-field/choices"].as_array().ok_or("choices required")?{
    let id=next_answer;next_answer+=1;ids.push(id);
    let uuid=a[":answer/id"].as_str().ok_or("answer UUID required")?;
    if by_uuid.insert(uuid.to_owned(),id).is_some(){return Err("duplicate answer UUID".into())}
    if uuid==correct_uuid{correct=Some(id)}
    entities.insert(id,record(json!({"answer/type":a[":answer/type"].as_str().ok_or("answer type required")?.trim_start_matches(':'),"answer/value":a[":answer/value"]})));
   }
   let correct=correct.ok_or("correct answer must belong to its field")?;
   entities.insert(field_id,record(json!({"answer-field/key":f[":answer-field/key"],"answer-field/type":f[":answer-field/type"].as_str().ok_or("field type required")?.trim_start_matches(':'),"answer-field/choices":ids,"answer-field/correct":correct})));
   maps.push(by_uuid);
  }
  entities.insert(10,record(json!({"question/id":"batch-generator-fixture","question/problem":q[":question/problem"],"question/answer-fields":field_ids})));
  entities.insert(11,record(json!({"knowledge-point/title":item["record"]["knowledge_point"]["title"],"knowledge-point/questions":[10]})));
  let snapshot=EntitySnapshot::new(entities,0)?;let mut checks=vec![];
  for check in item["checks"].as_array().ok_or("checks required")?{
   let i=check["field_index"].as_u64().unwrap_or(0)as usize;
   if i>=fields.len(){return Err("field_index out of range".into())}
   let submitted=if let Some(uuid)=check["submitted_answer_id"].as_str(){maps[i].get(uuid).ok_or("selected UUID not in field")?.to_string()}
    else{check["submitted"].as_str().ok_or("submission required")?.to_owned()};
   let result=learning::grade_field(&snapshot,10,field_ids[i],&submitted);
   let outcome=match &result{Ok(true)=>"accepted",Ok(false)=>"rejected",Err(_)=>"unresolved"};
   let expected=check["expected"].as_str().ok_or("expected result required")?;
   if outcome!=expected{return Err(format!("{} field {}: {:?} expected {}, got {} ({:?})",item["label"],i,submitted,expected,outcome,result).into())}
   match outcome{"accepted"=>accepted+=1,"rejected"=>rejected+=1,_=>unresolved+=1}
   checks.push(json!({"field_index":i,"submitted":submitted,"outcome":outcome,"reason":result.err(),"purpose":check["purpose"]}));
  }
  reports.push(json!({"label":item["label"],"template":item["record"]["generation"]["template"],"checks":checks}));
 }
 fs::write(&args[1],serde_json::to_string_pretty(&json!({"database_writes":0,"entry_point":"course_academy_engine::learning::grade_field","records":reports,"accepted_checks":accepted,"rejected_checks":rejected,"documented_unresolved_checks":unresolved}))?+"\n")?;
 println!("Native grading: {accepted} accepted, {rejected} rejected, {unresolved} explicitly unresolved; no database operations.");Ok(())
}
//! Difficulty-first sampling. A task and its completed prefix seed a stable
//! draw, so rereading or retrying a continuation cannot reshuffle its question.
use crate::{Result, schema::EntitySnapshot};
use sha2::{Digest, Sha256};
use std::collections::BTreeSet;

const BANDS: [&str; 3] = ["easy", "moderate", "hard"];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Phase {
    Initial,
    Remedial,
}

/// Lessons and reviews use their existing question-count phase rules.
/// Assessments must request a phase explicitly: a long quiz is not remedial.
pub fn weights(
    s: &EntitySnapshot,
    policy: u64,
    activity_type: &str,
    answered: usize,
) -> Result<Option<[f64; 3]>> {
    let initial_count = match activity_type {
        "lesson" => 2,
        "review" => 3,
        _ => return Err("question-count phases support lessons and reviews; assessments require an explicit phase".into()),
    };
    weights_for_phase(
        s,
        policy,
        activity_type,
        if answered < initial_count {
            Phase::Initial
        } else {
            Phase::Remedial
        },
    )
}

pub fn weights_for_phase(
    s: &EntitySnapshot,
    policy: u64,
    activity_type: &str,
    phase: Phase,
) -> Result<Option<[f64; 3]>> {
    if !matches!(activity_type, "lesson" | "review" | "assessment") {
        return Err("unsupported question-weight activity type".into());
    }
    let selected_phase = match phase {
        Phase::Initial => "initial",
        Phase::Remedial => "remedial",
    };
    let mut types = BTreeSet::new();
    let mut selected = None;
    for child in s.refs(policy, "policy/question-selection-weights")? {
        if s.owners(child, "policy/question-selection-weights")? != [policy] {
            return Err("question weights must have exactly one policy owner".into());
        }
        let kind = s.ident(&serde_json::json!(
            s.reference(child, "question-weights/activity-type")?
        ))?;
        if !matches!(
            kind.as_str(),
            "activity.type/lesson" | "activity.type/review" | "activity.type/assessment"
        ) || !types.insert(kind.clone())
        {
            return Err(
                "policy needs at most one question-weight record per supported activity type"
                    .into(),
            );
        }
        for phase in ["initial", "remedial"] {
            let mut distribution = [0.0; 3];
            for (index, band) in BANDS.iter().enumerate() {
                let key = format!("question-weights/{phase}-{band}");
                distribution[index] = s
                    .entity(child)?
                    .get(&key)
                    .and_then(|v| v.as_f64())
                    .filter(|v| v.is_finite() && *v >= 0.0)
                    .ok_or_else(|| format!("{key} must be finite and nonnegative"))?;
            }
            let total: f64 = distribution.iter().sum();
            if !total.is_finite() || total <= 0.0 {
                return Err(
                    "each question-weight distribution needs a positive finite total".into(),
                );
            }
            if kind == format!("activity.type/{activity_type}") && phase == selected_phase {
                selected = Some(distribution);
            }
        }
    }
    Ok(selected)
}

pub fn active_policy(s: &EntitySnapshot) -> Result<u64> {
    let policies = s.entities.with_attribute("policy/id");
    match policies.as_slice() {
        [policy] => Ok(*policy),
        _ => Err("question selection requires exactly one configured policy".into()),
    }
}

/// Exclude previous tasks; the caller separately excludes its current prefix.
/// This also lets completion validate an already-reserved current question.
pub fn seen_before_task(s: &EntitySnapshot, learner: u64, task: u64) -> Result<BTreeSet<u64>> {
    let mut seen = BTreeSet::new();
    for other in s.refs(learner, "learner/activity")? {
        if other == task {
            continue;
        }
        for item in s.refs(other, "learner-task/items")? {
            if let Some(content) = s.optional_ref(item, "task-item/content")? {
                seen.insert(content);
            }
        }
    }
    Ok(seen)
}

/// Candidates must already be fresh and usable. Unknown ratings are a uniform
/// fallback only when no eligible, positively weighted rated band remains.
/// Explicitly zero-weight rated bands are never used as that fallback.
pub fn select(
    s: &EntitySnapshot,
    candidates: &[u64],
    distribution: Option<[f64; 3]>,
    seed: &str,
) -> Result<Option<u64>> {
    let candidates: Vec<_> = candidates
        .iter()
        .copied()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    // Preserve old, unconfigured policies; the default policy supplies weights.
    let Some(distribution) = distribution else {
        return Ok(candidates.first().copied());
    };
    if distribution.iter().any(|w| !w.is_finite() || *w < 0.0)
        || !distribution.iter().sum::<f64>().is_finite()
        || distribution.iter().sum::<f64>() <= 0.0
    {
        return Err("invalid question-weight distribution".into());
    }
    let mut bands: [Vec<u64>; 3] = std::array::from_fn(|_| vec![]);
    let mut unrated = vec![];
    for q in candidates {
        let Some(value) = s
            .entity(q)?
            .get("question/difficulty")
            .filter(|v| !v.is_null())
        else {
            unrated.push(q);
            continue;
        };
        let difficulty = s.ident(value)?;
        let band = BANDS
            .iter()
            .position(|b| difficulty == format!("question.difficulty/{b}"))
            .ok_or("question has an unsupported difficulty enum")?;
        bands[band].push(q);
    }
    let digest = Sha256::digest(format!("course-academy/question-selection/v1/{seed}"));
    let uniform = |offset| {
        let bits = u64::from_be_bytes(digest[offset..offset + 8].try_into().unwrap()) >> 11;
        bits as f64 / (1u64 << 53) as f64
    };
    let total: f64 = distribution
        .iter()
        .enumerate()
        .filter(|(i, _)| !bands[*i].is_empty())
        .map(|(_, w)| *w)
        .sum();
    let pool = if total > 0.0 {
        let mut draw = uniform(0) * total;
        let mut chosen = None;
        for (i, w) in distribution.iter().enumerate() {
            if bands[i].is_empty() || *w == 0.0 {
                continue;
            }
            chosen = Some(i);
            if draw < *w {
                break;
            }
            draw -= *w;
        }
        &bands[chosen.unwrap()]
    } else {
        &unrated
    };
    Ok(if pool.is_empty() {
        None
    } else {
        Some(pool[(uniform(8) * pool.len() as f64) as usize])
    })
}

